# -*- coding: utf-8 -*-
import json

def build_search_js(OUT, comms, live):
    idx = {
        'c': [{'n': c['name'], 's': c['slug'], 'q': c['q4'], 'a': c['area']} for c in comms],
        'b': sorted({o['builder'] for o in live}),
    }
    js = SEARCH_PRE + json.dumps(idx) + SEARCH_POST
    open(f'{OUT}/assets/search.js', 'w').write(js)

def append_css(OUT):
    css = open(f'{OUT}/assets/site.css').read()
    if '.hsearch' not in css:
        with open(f'{OUT}/assets/site.css', 'a') as f:
            f.write(EXTRA_CSS)

